var transfer = new Transfer() { Id = transferId, BatchId = batchId, Username = username, Direction = TransferDirection.Download, Filename = file.Filename, Size = file.Size, RequestedAt = DateTime.UtcNow, State = TransferStates.Queued | TransferStates.Locally };
context.Add(transfer);
foreach (var record in existingRecordsNotYetRemoved.Where(t => t.Filename == file.Filename && !t.Removed)) { record.Removed = true; context.Update(record); }
context.SaveChanges();

Transfers.Downloads.TryCancel(guid);
if (remove) { Transfers.Downloads.Remove(guid); }
return NoContent(); // TryCancel fallback: t.State = Completed|Cancelled; t.EndedAt = UtcNow; t.Exception = new OperationCanceledException().Message; Update(t)

Transfers.Uploads.TryCancel(guid); // only cancels in-memory CTS; row finalized by upload task failure path
if (remove) { Transfers.Uploads.Remove(guid); }
return NoContent();

ActivateConversation(username);
await SoulseekClient.SendPrivateMessageAsync(username, message);
using var context = ContextFactory.CreateDbContext();
context.PrivateMessages.Add(new PrivateMessage { Timestamp = DateTime.UtcNow, Id = 0, Username = username, Direction = MessageDirection.Out, Message = message, IsAcknowledged = true });
context.SaveChanges();

var unAckedMessages = context.PrivateMessages.AsNoTracking().Where(m => !m.IsAcknowledged).ToList();
var conversations = context.Conversations.AsNoTracking().Where(expression).OrderBy(c => c.Username).ToList();
var response = conversations.Select(c => new Conversation { Username = c.Username, IsActive = c.IsActive, UnAcknowledgedMessageCount = unAckedMessages.Count(m => m.Username == c.Username) });

await AcknowledgeAsync(username);
var conversation = context.Conversations.FirstOrDefault(c => c.Username == username);
if (conversation != default) { conversation.IsActive = false; context.SaveChanges(); }

var token = Client.GetNextToken();
var search = new Search() { SearchText=query.SearchText, Token=token, Id=id, State=SearchStates.Requested, StartedAt=DateTime.UtcNow };
context.Add(search);
context.SaveChanges();
await SearchHub.BroadcastCreateAsync(search);

var selector = context.Searches.AsNoTracking().Where(expression);
if (!includeResponses) selector = selector.WithoutResponses();
return selector.FirstOrDefaultAsync();

using var context = ContextFactory.CreateDbContext();
context.Searches.Remove(search);
context.SaveChanges();
await SearchHub.BroadcastDeleteAsync(search);

@event = eventType switch {
    EventType.DownloadFileComplete => new DownloadFileCompleteEvent { ... },
    EventType.Noop => new NoopEvent(),
    _ => throw new SlskdException(...) };
EventBus.Raise(@event);
return StatusCode(201, @event);
